from __future__ import absolute_import

import time

from selenium.common.exceptions import NoSuchElementException
from selenium.webdriver.common.by import By
from taf.selenium.sbts_fsm3.pages import v23r1, v24r1
from taf.selenium.sbts_fsm3.pages.navigatable_page import NavigatablePage
from taf.selenium.sbts_fsm3.pages.panels.view import ViewPanel


class Diagnostic(v24r1.Diagnostic):
    """
    The class corresponding to diagnostic page on sbts web, all operations under diagnostic
    page will be implemented or added in its corresponding classes.
    """

    def __init__(self, driver, download_checker):
        super(Diagnostic, self).__init__(driver, download_checker)
        self._lte_downlink = TestModelsLTEDownlinkPage(driver, download_checker)
        self._downlink = TestModelsNRDownlinkPage(driver)
        self._vswr_tx_power_threshold = TestModelsVswrTxPowerThresholdPage(driver)

    @property
    def vwsr_tx_power_threshold(self):
        return self._vswr_tx_power_threshold


class TestModelsLTEDownlinkPage(v23r1.diagnostic.TestModelsLTEDownlinkPage):
    def __init__(self, driver, download_checker):
        super(TestModelsLTEDownlinkPage, self).__init__(driver, download_checker)
        self._view_panel = TestModelsLTEDownlinkPageViewPanel(driver, download_checker)


class TestModelsLTEDownlinkPageViewPanel(v23r1.diagnostic.TestModelsLTEDownlinkPageViewPanel):
    _LOCAL_CELL_LIST_BUTTON_XPATH = '//div[contains(text(), "Local cell")]/parent::*//p-dropdown'
    _LOCAL_CELL_DROPDOWN_LIST_OPTIONS_XPATH = '//ul[@role="listbox"]//li'
    _TEST_MODEL_LIST_BUTTON_XPATH = '//div[contains(text(), "Test model")]/parent::*//p-dropdown'
    _TEST_MODEL_DROPDOWN_LIST_OPTIONS_XPATH = '//ul[@role="listbox"]//li'
    _PHYSICAL_CELL_ID_INPUT_XPATH = '//div[contains(text(), "Physical cell ID")]/parent::*//input'
    _UL_DL_CONFIGURATION_XPATH = '//div[contains(text(), "UL/DL configuration")]/parent::*//label[text()={}]'
    _START_TEST_BUTTON_XPATH = '//button[*[contains(text(), "Start Test")]]'
    _TEST_TABLE_PROGRESS_CELL_XPATH = '//div[contains(text(), "Started tests")]/parent::*/parent::*//tr[{}]/td[4]'
    _STOP_TEST_BUTTON_XPATH = '//div[contains(text(), "Started tests")]/parent::*/parent::*//tr[{}]//button'

    def __init__(self, driver, download_checker):
        super(TestModelsLTEDownlinkPageViewPanel, self).__init__(driver, download_checker)


class TestModelsNRDownlinkPage(v23r1.diagnostic.TestModelsNRDownlinkPage):
    def __init__(self, driver):
        super(TestModelsNRDownlinkPage, self).__init__(driver)
        self._view_panel = TestModelsNRDownlinkPageViewPanel(driver)

    def start_test(self, local_cell, test_model, p_max, timeout, polarization, physical_cell_id=None,
                   beam_id=None, nrarfcn_downlink=None, nrarfcn_uplink=None, nrarfcn=None, type_of_load=None,
                   level_of_load_flat=None, level_of_load_burst=None, spec_ssb_beam_pattern=None,
                   power_backoff=None, ru_mode=None, mimo_rank=None, enable_vswr=False):
        return self._view_panel.start_test(local_cell=local_cell, test_model=test_model, p_max=p_max,
                                           timeout=timeout, polarization=polarization,
                                           physical_cell_id=physical_cell_id,
                                           beam_id=beam_id, nrarfcn=nrarfcn, type_of_load=type_of_load,
                                           level_of_load_burst=level_of_load_burst,
                                           level_of_load_flat=level_of_load_flat,
                                           spec_ssb_beam_pattern=spec_ssb_beam_pattern, power_backoff=power_backoff,
                                           ru_mode=ru_mode, mimo_rank=mimo_rank, enable_vswr=enable_vswr)

    def get_vswr_monitored_value(self):
        return self._view_panel.get_vswr_monitored_value()


class TestModelsNRDownlinkPageViewPanel(v23r1.diagnostic.TestModelsNRDownlinkPageViewPanel):
    _MIMO_RANK_DROPDOWN_LIST_BUTTON_XPATH = '//div[contains(text(), "MIMO rank")]/parent::*//button'
    _MIMO_RANK_DROPDOWN_LIST_OPTIONS_XPATH = '//div[contains(text(), "MIMO rank")]/parent::*//ul//li'
    _ENABLE_VSWR = '//div[contains(text(), "Enable VSWR monitoring")]/parent::*//input'

    def _configure_downlink_test(self, local_cell, test_model, p_max, timeout, polarization, physical_cell_id=None,
                                 beam_id=None, nrarfcn_downlink=None, nrarfcn_uplink=None, nrarfcn=None,
                                 type_of_load=None, level_of_load_flat=None, level_of_load_burst=None,
                                 spec_ssb_beam_pattern=None, power_backoff=None, ru_mode=None, mimo_rank=None,
                                 enable_vswr=False):
        super(TestModelsNRDownlinkPageViewPanel, self)._configure_downlink_test(
            local_cell=local_cell,
            test_model=test_model,
            p_max=p_max,
            timeout=timeout,
            polarization=polarization,
            physical_cell_id=physical_cell_id,
            beam_id=beam_id,
            nrarfcn_downlink=nrarfcn_downlink,
            nrarfcn_uplink=nrarfcn_uplink,
            nrarfcn=nrarfcn,
            type_of_load=type_of_load,
            level_of_load_flat=level_of_load_flat,
            level_of_load_burst=level_of_load_burst,
            spec_ssb_beam_pattern=spec_ssb_beam_pattern
        )
        if power_backoff is not None:
            self.insert_text_to_enable_element((By.XPATH, self._POWER_BACKOFF), power_backoff, timeout)

        if ru_mode is not None:
            self.select_element_from_dropdown_list_by_text_and_click(
                ru_mode,
                (By.XPATH, self._RU_MODE_DROPDOWN_LIST_BUTTON_XPATH),
                (By.XPATH, self._RU_MODE_DROPDOWN_LIST_OPTIONS_XPATH),
                timeout
            )

        if mimo_rank is not None:
            self.select_element_from_dropdown_list_by_text_and_click(
                mimo_rank,
                (By.XPATH, self._MIMO_RANK_DROPDOWN_LIST_BUTTON_XPATH),
                (By.XPATH, self._MIMO_RANK_DROPDOWN_LIST_OPTIONS_XPATH),
                timeout
            )

        try:
            self.driver.find_element_by_xpath(self._ENABLE_VSWR)
            self.select_checkbox_by_specified_status(enable_vswr, self._ENABLE_VSWR, self._ENABLE_VSWR, use_js=True)
        except NoSuchElementException:
            pass

    def start_test(self, local_cell, test_model, p_max, timeout, polarization, physical_cell_id=None,
                   beam_id=None, nrarfcn_downlink=None, nrarfcn_uplink=None, nrarfcn=None, type_of_load=None,
                   level_of_load_flat=None, level_of_load_burst=None, spec_ssb_beam_pattern=None,
                   power_backoff=None, ru_mode=None, mimo_rank=None, enable_vswr=False):
        timeout = int(timeout)
        self._configure_downlink_test(local_cell=local_cell,
                                      test_model=test_model,
                                      p_max=p_max,
                                      timeout=timeout,
                                      polarization=polarization,
                                      physical_cell_id=physical_cell_id,
                                      beam_id=beam_id,
                                      nrarfcn_downlink=nrarfcn_downlink,
                                      nrarfcn_uplink=nrarfcn_uplink,
                                      nrarfcn=nrarfcn,
                                      type_of_load=type_of_load,
                                      level_of_load_flat=level_of_load_flat,
                                      level_of_load_burst=level_of_load_burst,
                                      spec_ssb_beam_pattern=spec_ssb_beam_pattern,
                                      power_backoff=power_backoff,
                                      ru_mode=ru_mode,
                                      mimo_rank=mimo_rank,
                                      enable_vswr=enable_vswr)

        self.click_enabled_element((By.XPATH, self._START_TEST_BUTTON_XPATH), timeout)

    def get_vswr_monitored_value(self):
        time.sleep(3)
        fixed_table_info = self._get_fixed_table_info()
        mutual_table_info = self._get_mutual_table_info()
        for index, value in enumerate(fixed_table_info):
            value.update(mutual_table_info[index])
        return fixed_table_info

    def _get_fixed_table_info(self):  # noqa: C901
        fixed_table_thead_th = '//vswr-monitoring-results-panels//div[@class="ant-monitoring-result-table-fixed"]//thead//th'
        fixed_table_tbody_tr = '//vswr-monitoring-results-panels//div[@class="ant-monitoring-result-table-fixed"]//tbody[@class="ng-scope"]/tr'

        fixed_table_titles = []
        for title_elem in self.driver.find_elements_by_xpath(fixed_table_thead_th):
            fixed_table_titles.append(title_elem.text.strip())

        tr_elems = self.driver.find_elements_by_xpath(fixed_table_tbody_tr)
        fixed_table_value = []

        for tr_elem in tr_elems:
            td_elems = tr_elem.find_elements_by_xpath("./td")

            td_values = []
            for td_elem in td_elems:
                td_values.append(td_elem.text)

            fixed_table_value.append(td_values)

        longest_td_value = max([len(value_list) for value_list in fixed_table_value])
        for index, item in enumerate(fixed_table_value):
            if longest_td_value == len(item):
                longest_item = item
                continue
            item.insert(0, longest_item[0])

        fixed_table = []
        for item in fixed_table_value:
            fixed_table.append(dict(zip(fixed_table_titles, item)))

        return fixed_table

    def _get_mutual_table_info(self):
        mutual_table_thead_th = ('//vswr-monitoring-results-panels//div[contains(@class, '
                                 '"ant-monitoring-result-table-container")]//thead//th')
        mutual_table_tbody_tr = ('//vswr-monitoring-results-panels//div[contains(@class, '
                                 '"ant-monitoring-result-table-container")]//tbody[@class="ng-scope"]/tr')

        mutual_table_titles = []
        for title_elem in self.driver.find_elements_by_xpath(mutual_table_thead_th):
            text = title_elem.text.replace('\n', ' ')
            mutual_table_titles.append(text)

        tr_elems = self.driver.find_elements_by_xpath(mutual_table_tbody_tr)
        mutual_table_value = []

        for tr_elem in tr_elems:
            td_elems = tr_elem.find_elements_by_xpath("./td")

            td_values = []
            for td_elem in td_elems:
                td_values.append(td_elem.text)

            mutual_table_value.append(td_values)

        mutual_table = []
        for item in mutual_table_value:
            mutual_table.append(dict(zip(mutual_table_titles, item)))

        return mutual_table


class TestModelsVswrTxPowerThresholdPage(NavigatablePage):
    _MENU_ROUTE_LIST = ['Diagnostic', 'Test Models', 'VSWR TX Power Level Threshold Configuration']

    def __init__(self, driver):
        super(TestModelsVswrTxPowerThresholdPage, self).__init__(driver)
        self._view_panel = TestModelsVswrTxPowerThresholdPageViewPanel(driver)

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST

    def configure_vswr_tx_power_threshold(self, radio_module, antenna, cell, tx_power_threshold):
        self._view_panel.configure_vswr_tx_power_threshold(radio_module, antenna, cell, tx_power_threshold)

    def upload_threshold(self):
        return self._view_panel.upload_threshold()

    def get_vswr_tx_power_configuration(self):
        return self._view_panel.get_vswr_tx_power_configuration()


class TestModelsVswrTxPowerThresholdPageViewPanel(ViewPanel):
    UPDATE_THRESHOLD = '//vswr-configuration//*[@class="vswr-send-button"]//button'
    UPDATE_THRESHOLD_STATUS = '//vswr-configuration//*[@class="vswr-send-button"]//ot-instruction'

    def __init__(self, driver):
        super(TestModelsVswrTxPowerThresholdPageViewPanel, self).__init__(driver)

    def configure_vswr_tx_power_threshold(self, radio_module, antenna, cell, tx_power_threshold):
        first_td = '//tr[td[contains(text(), "{}")]]//td[1]'.format(radio_module)
        tds_xpath = './/following-sibling::td[@class="p-element"]'

        first_td_elem = self.driver.find_element_by_xpath(first_td)
        cover_range = int(first_td_elem.get_attribute("rowspan"))

        tds_text = []
        for td_elem in first_td_elem.find_elements_by_xpath(tds_xpath):
            tds_text.append(td_elem.text.strip())

        if antenna in tds_text and cell in tds_text:
            tx_power_threshold_elem = first_td_elem.find_element_by_xpath(".//following-sibling::td//input")
            tx_power_threshold_elem.clear()
            tx_power_threshold_elem.send_keys(tx_power_threshold)
            return

        first_tr = '//tr[td[contains(text(), "{}")]]//following-sibling::tr'.format(radio_module)
        tds_text = []
        for tr_elem in self.driver.find_elements_by_xpath(first_tr)[: cover_range - 1]:

            for td in tr_elem.find_elements_by_xpath('.//td[@class="p-element"]'):
                tds_text.append(td.text.strip())

            if antenna in tds_text and cell in tds_text:
                tx_power_threshold_elem = tr_elem.find_element_by_xpath(".//input")
                tx_power_threshold_elem.clear()
                tx_power_threshold_elem.send_keys(tx_power_threshold)
                return

            tds_text = []

    def upload_threshold(self):
        self.click_enabled_element((By.XPATH, self.UPDATE_THRESHOLD))
        self.wait_for_text_present_in_element((By.XPATH, self.UPDATE_THRESHOLD_STATUS), "Ongoing")
        self.wait_for_text_not_present_in_element((By.XPATH, self.UPDATE_THRESHOLD_STATUS), "Ongoing")
        return self.get_text_by_xpath(self.UPDATE_THRESHOLD_STATUS)

    def get_vswr_tx_power_configuration(self):  # noqa: C901
        table_thead_th = '//vswr-configuration//div[@class="test-models-vswr-config"]//thead//tr[1]//th'
        table_tbody_tr = '//vswr-configuration//div[@class="test-models-vswr-config"]//tbody//tr'

        table_titles = []
        for title_elem in self.driver.find_elements_by_xpath(table_thead_th):
            table_titles.append(title_elem.text.strip())

        tr_elems = self.driver.find_elements_by_xpath(table_tbody_tr)
        if not tr_elems:
            return {}

        fixed_table_value = []
        for tr_elem in tr_elems:
            td_elems = tr_elem.find_elements_by_xpath("./td")

            td_values = []

            target_index = 3
            if len(td_elems) == 5:
                target_index = 2

            for index, td_elem in enumerate(td_elems):
                if index == target_index:
                    value = td_elem.find_element_by_xpath(".//ot-input-number").get_attribute("ng-reflect-model")
                    td_values.append(value)
                else:
                    td_values.append(td_elem.text)

            fixed_table_value.append(td_values)

        longest_td_value = max([len(value_list) for value_list in fixed_table_value])
        for index, item in enumerate(fixed_table_value):
            if longest_td_value == len(item):
                longest_item = item
                continue
            item.insert(0, longest_item[0])

        fixed_table = []
        for item in fixed_table_value:
            fixed_table.append(dict(zip(table_titles, item)))
        return fixed_table
